// === URL MAKER - Version ultra robuste pour loop ===

const items = $input.all(); // Récupère TOUS les items entrants

const output = [];

items.forEach((item, index) => {
    const inputData = item.json || {};
    let prompts = [];

    // Cas 1 : Objet avec prompt_1, prompt_2, prompt_3... (cas le plus courant après loop)
    if (typeof inputData === 'object' && !Array.isArray(inputData)) {
        for (const key in inputData) {
            if (key.startsWith('prompt_') && typeof inputData[key] === 'string') {
                const text = inputData[key].trim();
                if (text) {
                    prompts.push({ name: key, text: text });
                }
            }
        }
    }

    // Cas 2 : Un seul prompt (comportement ancien)
    if (prompts.length === 0) {
        const single = inputData.message?.content || 
                      inputData.output || 
                      inputData.text || 
                      inputData.prompt || 
                      inputData.prompt_genere || 
                      inputData.prompt_1 || "";   // sécurité supplémentaire

        if (single && typeof single === 'string' && single.trim()) {
            prompts.push({ name: `prompt_${index}`, text: single.trim() });
        }
    }

    // Cas 3 : Si c'est déjà un tableau de prompts
    if (prompts.length === 0 && Array.isArray(inputData)) {
        inputData.forEach((p, i) => {
            const text = typeof p === 'string' ? p : p.text || p.prompt || "";
            if (text) prompts.push({ name: `prompt_${i}`, text: text.trim() });
        });
    }

    if (prompts.length === 0) {
        console.warn(`Item ${index} : Aucun prompt trouvé`);
        return; // on saute cet item
    }

    // Génération des URLs pour chaque prompt trouvé
    prompts.forEach(p => {
        const encoded = encodeURIComponent(p.text);

        output.push({
            json: {
                prompt_name: p.name,
                prompt_genere: p.text,
                url_default: `https://image.pollinations.ai/prompt/${encoded}`,
                url_flux: `https://image.pollinations.ai/prompt/${encoded}?model=flux`,
                url_turbo: `https://image.pollinations.ai/prompt/${encoded}?model=turbo`
            }
        });
    });
});

if (output.length === 0) {
    throw new Error("Aucun prompt valide trouvé dans les données d'entrée.");
}

return output;

