// Récupère le prompt généré par DeepSeek
const raw = $input.first().json.output || $input.first().json.text || "";
const jsonMatch = raw.match(/"final_prompt"\s*:\s*"([\s\S]*?)"\s*\}/);
const prompt = jsonMatch 
  ? jsonMatch[1] 
  : raw.replace(/<think>[\s\S]*?<\/think>/gi, "").trim();

// best_image est un tableau — on prend le premier élément
const rawImg = $('Condition').first().json.best_image;
const cleanBase64 = Array.isArray(rawImg) ? rawImg[0] : rawImg;

// Construit le body pour l'API Forge (img2img)
const requestBody = {
  prompt: prompt + ", use the provided image as a visual draft and reference for composition, subject, and style",
  negative_prompt: "lowres, bad anatomy, bad hands, text, error, missing fingers, extra digit, fewer digits, cropped, worst quality, low quality, normal quality, jpeg artifacts, signature, watermark, username, blurry",
  init_images: [cleanBase64],
  denoising_strength: 0.6,
  width: 768,
  height: 768,
  steps: 30,
  cfg_scale: 8,
  sampler_name: "DPM++ 2M Karras"
};

return {
  json: {
    body: requestBody,
    prompt_used: prompt
  }
};

